structured.sparql:
SELECT ?stage ?eventUid ?actor ?timestamp ?operation ?cmdLine
WHERE {
  {
    ?api a :ApiEvent ;
         :eventUid ?eventUid ;
         :operation "OAuth consent" ;
         :startTime ?timestamp ;
         :actor ?actor .
    BIND("OAuth consent" AS ?stage)
    BIND(UNDEF AS ?operation)
    BIND(UNDEF AS ?cmdLine)
  }
  UNION
  {
    ?proc a :Process ;
          :eventUid ?eventUid ;
          :cmdLine ?cmdLine ;
          :host ?host ;
          :startTime ?timestamp .
    FILTER(CONTAINS(?cmdLine, "powershell") || CONTAINS(LCASE(?cmdLine), "powershell"))
    BIND("PowerShell execution" AS ?stage)
    BIND(UNDEF AS ?actor)
    BIND(UNDEF AS ?operation)
  }
  UNION
  {
    ?sess a :Session ;
          :eventUid ?eventUid ;
          :startTime ?timestamp ;
          :host ?host .
    BIND("C2 beacon" AS ?stage)
    BIND(UNDEF AS ?actor)
    BIND(UNDEF AS ?operation)
    BIND(UNDEF AS ?cmdLine)
  }
  UNION
  {
    ?sess a :Session ;
          :eventUid ?eventUid ;
          :startTime ?timestamp ;
          :host ?host .
    BIND("Lateral connection" AS ?stage)
    BIND(UNDEF AS ?actor)
    BIND(UNDEF AS ?operation)
    BIND(UNDEF AS ?cmdLine)
  }
  UNION
  {
    ?api a :ApiEvent ;
         :eventUid ?eventUid ;
         :operation "AssumeRole" ;
         :mfaPresent false ;
         :startTime ?timestamp ;
         :actor ?actor .
    BIND("No-MFA privilege escalation" AS ?stage)
    BIND(UNDEF AS ?operation)
    BIND(UNDEF AS ?cmdLine)
  }
  UNION
  {
    ?api a :ApiEvent ;
         :eventUid ?eventUid ;
         :operation "AssumeRole" ;
         :startTime ?timestamp ;
         :actor ?actor .
    BIND("Role assumption" AS ?stage)
    BIND(UNDEF AS ?operation)
    BIND(UNDEF AS ?cmdLine)
  }
  UNION
  {
    ?api a :ApiEvent ;
         :eventUid ?eventUid ;
         :operation "GetObject" ;
         :startTime ?timestamp ;
         :actor ?actor .
    BIND("Data exfiltration" AS ?stage)
    BIND(UNDEF AS ?operation)
    BIND(UNDEF AS ?cmdLine)
  }
}
ORDER BY ?timestamp

SELECT ?eventUid ?operation ?cmdLine ?startTime ?endTime ?stageType
WHERE {
  {
    ?event a :ApiEvent ;
           :eventUid ?eventUid ;
           :operation ?operation ;
           :startTime ?startTime .
    BIND("api_event" AS ?stageType)
  }
  UNION
  {
    ?event a :Process ;
           :eventUid ?eventUid ;
           :cmdLine ?cmdLine ;
           :startTime ?startTime .
    BIND("process" AS ?stageType)
  }
  UNION
  {
    ?event a :Session ;
           :eventUid ?eventUid ;
           :startTime ?startTime ;
           :endTime ?endTime .
    BIND("session" AS ?stageType)
  }
}
ORDER BY ASC(?startTime)

SELECT ?stage ?eventUid ?startTime WHERE {
  { ?proc a :Process ; :eventUid ?eventUid ; :startTime ?startTime . FILTER(REGEX(?cmdLine, "powershell", "i")) }
  UNION
  { ?api a :ApiEvent ; :eventUid ?eventUid ; :startTime ?startTime ; :operation ?op . FILTER(?op IN ("oauth_consent", "AssumeRole", "privilege_escalation", "data_exfiltration")) }
  UNION
  { ?sess a :Session ; :eventUid ?eventUid ; :startTime ?startTime }
} ORDER BY ?startTime

SELECT ?event ?type ?operation ?cmdLine ?actor ?startTime ?endTime
WHERE {
  { ?event a :Process ; :cmdLine ?cmdLine ; :startTime ?startTime }
  UNION
  { ?event a :ApiEvent ; :operation ?operation ; :actor ?actor ; :startTime ?startTime }
  UNION
  { ?event a :Session ; :startTime ?startTime ; :endTime ?endTime }
}
ORDER BY ?startTime

SELECT ?eventUid ?eventType ?operation ?cmdLine ?startTime ?endTime
WHERE {
  {
    ?event a :ApiEvent ;
           :eventUid ?eventUid ;
           :operation ?operation ;
           :startTime ?startTime .
    BIND("ApiEvent" AS ?eventType)
  }
  UNION
  {
    ?event a :Process ;
           :eventUid ?eventUid ;
           :cmdLine ?cmdLine ;
           :startTime ?startTime .
    BIND("Process" AS ?eventType)
  }
  UNION
  {
    ?event a :Session ;
           :eventUid ?eventUid ;
           :startTime ?startTime ;
           :endTime ?endTime .
    BIND("Session" AS ?eventType)
  }
}
ORDER BY ?startTime

SELECT (xsd:integer((xsd:dateTime(?endTime) - xsd:dateTime(?startTime)) / xsd:dayTimeDuration('PT1S')) AS ?dwellTimeSeconds)
WHERE {
  ?session a :Session ;
    :startTime ?startTime ;
    :endTime ?endTime .
}
LIMIT 1

SELECT ((xsd:dateTime(?endTime) - xsd:dateTime(?startTime)) / xsd:dayTimeDuration("PT1S") AS ?dwellTimeSeconds)
WHERE {
  ?session a :Session ;
           :startTime ?startTime ;
           :endTime ?endTime .
}
LIMIT 1

SELECT ((MAX(?endTime) - MIN(?startTime)) AS ?dwellTimeSeconds)
WHERE {
  ?event a :Session ;
         :startTime ?startTime ;
         :endTime ?endTime .
}

SELECT (COUNT(DISTINCT ?host) AS ?distinctAssets)
WHERE {
  ?apiEvent a :ApiEvent ;
            :actor ?actorId ;
            :eventUid ?uid .
  ?process a :Process ;
           :eventUid ?uid ;
           :host ?host .
}
GROUP BY ?actorId

SELECT (COUNT(DISTINCT ?host) as ?count)
WHERE {
  ?event a :ApiEvent ;
    :actor ?actor ;
    :host ?host .
  FILTER (BOUND(?host))
}

SELECT COUNT(DISTINCT ?asset) AS ?count
WHERE {
  ?apiEvent a :ApiEvent ;
            :actor ?actor ;
            :host ?host .
  ?host :representsAsset ?asset .
}
GROUP BY ?actor
HAVING COUNT(DISTINCT ?asset) > 0
LIMIT 1
